const body = $input.first().json.body || $input.first().json;
const data = body.data || {};
const message = data.message || {};
const key = data.key || {};

if (body.event !== 'messages.upsert') {
  return [{ json: { skip: true, reason: 'not_upsert' } }];
}
if (key.fromMe) {
  return [{ json: { skip: true, reason: 'own_message' } }];
}
const remoteJid = key.remoteJid || '';
if (remoteJid.includes('@g.us')) {
  return [{ json: { skip: true, reason: 'group' } }];
}

const phoneNumber = remoteJid.replace('@s.whatsapp.net', '');
const instance = body.instance || '';

let messageType = 'other';
let textContent = '';
let locationLat = null;
let locationLng = null;
let selectedCategory = null;

if (message.conversation || message.extendedTextMessage) {
  messageType = 'text';
  textContent = (message.conversation || message.extendedTextMessage?.text || '').trim();
} else if (message.locationMessage || message.liveLocationMessage) {
  messageType = 'location';
  const loc = message.locationMessage || message.liveLocationMessage;
  locationLat = loc.degreesLatitude;
  locationLng = loc.degreesLongitude;
} else if (message.listResponseMessage) {
  messageType = 'listResponse';
  selectedCategory = message.listResponseMessage.singleSelectReply?.selectedRowId || '';
} else if (message.buttonsResponseMessage) {
  messageType = 'text';
  textContent = message.buttonsResponseMessage.selectedButtonId || '';
}

return [{ json: {
  skip: false, messageType, phoneNumber, remoteJid,
  instance, textContent, locationLat, locationLng, selectedCategory
} }];

const parsed = $('Parse Payload').first().json;
const { phoneNumber, remoteJid, instance } = parsed;
const lat = parsed.locationLat;
const lng = parsed.locationLng;

const listPayload = {
  number: remoteJid,
  listMessage: {
    title: 'وين تبغى تروح؟ 🗺️',
    description: 'استلمت موقعك ✅\nاختر نوع المكان:',
    buttonText: 'اعرض الخيارات ↓',
    footerText: 'وين أروح',
    sections: [
      { title: '🍽️ طعام وشراب', rows: [
        { rowId: 'restaurant', title: '🍽️ مطعم', description: 'أقرب مطاعم حولك' },
        { rowId: 'cafe', title: '☕ مقهى / كافيه', description: 'أقرب مقاهي' },
        { rowId: 'bakery', title: '🥖 مخبز / حلويات', description: 'أقرب مخابز' }
      ]},
      { title: '💊 صحة وطوارئ', rows: [
        { rowId: 'pharmacy', title: '💊 صيدلية', description: 'أقرب صيدلية' },
        { rowId: 'hospital', title: '🏥 مستشفى / عيادة', description: 'أقرب مستشفى' }
      ]},
      { title: '🛍️ خدمات يومية', rows: [
        { rowId: 'supermarket', title: '🛒 بقالة / سوبرماركت' },
        { rowId: 'gas_station', title: '⛽ محطة بنزين' },
        { rowId: 'atm', title: '🏧 صراف آلي' }
      ]},
      { title: '🕌 أخرى', rows: [
        { rowId: 'mosque', title: '🕌 مسجد' },
        { rowId: 'park', title: '🌳 حديقة / منتزه' },
        { rowId: 'lodging', title: '🏨 فندق / استراحة' }
      ]}
    ]
  }
};

return [{ json: { phoneNumber, remoteJid, instance, lat, lng, city: null, listPayload } }];

const parsed = $('Parse Payload').first().json;
const session = $('Load Session from Redis').first().json;

const { phoneNumber, remoteJid, instance, selectedCategory } = parsed;

if (!session.found || !session.lat || !session.lng) {
  return [{ json: {
    action: 'no_location', remoteJid, instance,
    replyText: 'انتهت جلستك 😅\nأرسل موقعك مجدداً أو اكتب اسم مدينتك 📍'
  }}];
}

const placeLabels = {
  restaurant:'مطعم', cafe:'مقهى', pharmacy:'صيدلية', hospital:'مستشفى',
  supermarket:'سوبرماركت', mosque:'مسجد', gas_station:'محطة بنزين',
  atm:'صراف آلي', bakery:'مخبز', park:'حديقة', lodging:'فندق'
};

return [{ json: {
  action: 'search', remoteJid, instance, phoneNumber,
  lat: session.lat, lng: session.lng,
  placeType: selectedCategory,
  placeLabel: placeLabels[selectedCategory] || selectedCategory,
  radius: session.city ? 5000 : 2000,
  city: session.city || null,
  searchBody: {
    lat: session.lat, lng: session.lng,
    place_type: selectedCategory,
    radius: session.city ? 5000 : 2000,
    max_results: 5, phone_number: phoneNumber
  }
}}];

const parsed = $('Parse Payload').first().json;
const session = $('Load Session from Redis').first().json;
const { phoneNumber, remoteJid, instance, textContent: text } = parsed;

const CITIES = {
  'رياض':{lat:24.7136,lng:46.6753,name:'الرياض'},
  'الرياض':{lat:24.7136,lng:46.6753,name:'الرياض'},
  'جدة':{lat:21.4858,lng:39.1925,name:'جدة'},
  'جده':{lat:21.4858,lng:39.1925,name:'جدة'},
  'مكة':{lat:21.3891,lng:39.8579,name:'مكة المكرمة'},
  'مكه':{lat:21.3891,lng:39.8579,name:'مكة المكرمة'},
  'المدينة':{lat:24.5247,lng:39.5692,name:'المدينة المنورة'},
  'المدينه':{lat:24.5247,lng:39.5692,name:'المدينة المنورة'},
  'دمام':{lat:26.4207,lng:50.0888,name:'الدمام'},
  'الدمام':{lat:26.4207,lng:50.0888,name:'الدمام'},
  'الخبر':{lat:26.2794,lng:50.2046,name:'الخبر'},
  'كويت':{lat:29.3759,lng:47.9774,name:'الكويت'},
  'الكويت':{lat:29.3759,lng:47.9774,name:'الكويت'},
  'دبي':{lat:25.2048,lng:55.2708,name:'دبي'},
  'أبوظبي':{lat:24.4539,lng:54.3773,name:'أبوظبي'},
  'ابوظبي':{lat:24.4539,lng:54.3773,name:'أبوظبي'},
  'الشارقة':{lat:25.3463,lng:55.4209,name:'الشارقة'},
  'حائل':{lat:27.5219,lng:41.7057,name:'حائل'},
  'تبوك':{lat:28.3998,lng:36.5714,name:'تبوك'},
  'أبها':{lat:18.2164,lng:42.5053,name:'أبها'}
};

// طلب عرض القائمة صراحةً
if (['قائمة','القائمة','خيارات','menu','list'].includes(text.toLowerCase())) {
  if (session.found && session.lat) {
    return [{ json: { action: 'send_list', remoteJid, instance, listDescription: 'اختر نوع المكان 👇' }}];
  }
  return [{ json: { action: 'send_welcome', remoteJid, instance }}];
}

// رد على رقم المكان (1-5)
if (/^[1-5]$/.test(text) && session.found) {
  return [{ json: {
    action: 'send_welcome', remoteJid, instance,
    customMsg: 'هذه الميزة قادمة قريباً 🚧\nاكتب نوع مكان للبحث مجدداً'
  }}];
}

// كشف اسم المدينة
const cityMatch = CITIES[text] || CITIES[text.replace(/^ال/,'')];
if (cityMatch) {
  return [{ json: {
    action: 'save_city_then_list',
    remoteJid, instance, phoneNumber,
    lat: cityMatch.lat, lng: cityMatch.lng,
    city: cityMatch.name,
    listDescription: `📍 بحث في: *${cityMatch.name}*\nاختر نوع المكان:`
  }}];
}

// لا يوجد موقع → ترحيب
if (!session.found || !session.lat || !session.lng) {
  return [{ json: { action: 'send_welcome', remoteJid, instance }}];
}

// مستخدم عائد بدون موقع جديد → كشف النية
return [{ json: {
  action: 'call_intent',
  remoteJid, instance, phoneNumber,
  text,
  lat: session.lat, lng: session.lng,
  radius: session.city ? 5000 : 2000,
  city: session.city || null,
  lastPlaceType: session.last_place_type || null
}}];

