const intent = $json;
const ctx = $('Handle Text').first().json;

if (!intent.place_type) {
  return [{ json: {
    action: 'send_list', instance: ctx.instance,
    remoteJid: ctx.remoteJid,
    listDescription: 'لم أفهم ما تبحث عنه 😅\nاختر من القائمة:'
  }}];
}

return [{ json: {
  action: 'search',
  remoteJid: ctx.remoteJid, instance: ctx.instance,
  phoneNumber: ctx.phoneNumber,
  searchBody: {
    lat: ctx.lat, lng: ctx.lng,
    place_type: intent.place_type,
    radius: ctx.radius || 2000,
    max_results: 5,
    phone_number: ctx.phoneNumber
  }
}}];

const d = $json;
if (d.action === 'no_location') {
  return [{ json: { _skip_search: true, remoteJid: d.remoteJid, instance: d.instance, replyText: d.replyText } }];
}
return [{ json: d }];

const result = $json;
let remoteJid, instance;
try { const src = $('Build List-Response Search').first().json; remoteJid = src.remoteJid; instance = src.instance; } catch(_) {}
try { if (!remoteJid) { const src = $('Prepare Text Search').first().json; remoteJid = src.remoteJid; instance = src.instance; } } catch(_) {}

const message = result.formatted_message || 'عذراً، لم أجد نتائج قريبة. جرّب نوعاً آخر أو موقعاً مختلفاً 😅';
return [{ json: { remoteJid, instance, message } }];
